package libc

import (
	"os"
	"strconv"
	"strings"
	"testing"
	"unsafe"
)

// TestSscanfVsHostReference compares c2go Sscanf against the host's sscanf for
// a battery of integer/string cases generated by /tmp/c2godbg/scanf_ref_gen.c
// into /tmp/scanf_ref.txt (skipped when absent — it is a host-specific
// verification artifact, not a committed fixture; mirrors #582's zz_fpref).
//
// Lines are "fmt|input|ret|val". Known host(BSD/macOS)≠musl divergences on
// out-of-range / invalid-digit overflow are whitelisted (musl saturates via
// __intscan's lim clamp; BSD truncates differently) — the c2go port follows
// musl, so those are expected differences, not bugs.
func TestSscanfVsHostReference(t *testing.T) {
	data, err := os.ReadFile("/tmp/scanf_ref.txt")
	if err != nil {
		t.Skip("no /tmp/scanf_ref.txt reference (run scanf_ref_gen.c first)")
	}
	// (fmt|input) pairs where host BSD scanf and musl legitimately differ on
	// overflow/invalid-tail handling. Verified by hand against musl semantics.
	hostDiffs := map[string]bool{}

	intFmt := func(f string) bool {
		return strings.ContainsAny(f, "diouxX")
	}

	var mismatches int
	for _, line := range strings.Split(strings.TrimRight(string(data), "\n"), "\n") {
		if line == "" {
			continue
		}
		parts := strings.SplitN(line, "|", 4)
		if len(parts) != 4 {
			continue
		}
		fmtStr, input, retStr, wantVal := parts[0], parts[1], parts[2], parts[3]
		wantRet, _ := strconv.Atoi(retStr)
		key := fmtStr + "|" + input

		if intFmt(fmtStr) {
			d := new(int64)
			n := ssf(t, input, fmtStr, unsafe.Pointer(d))
			gotVal := strconv.FormatInt(*d, 10)
			if int(n) != wantRet || (wantRet == 1 && gotVal != wantVal) {
				if hostDiffs[key] {
					continue
				}
				mismatches++
				t.Errorf("Sscanf(%q,%q) = ret %d val %s; host ret %d val %s",
					input, fmtStr, n, gotVal, wantRet, wantVal)
			}
		} else {
			b, p := strDest(64)
			n := ssf(t, input, fmtStr, p)
			gotVal := cstr(&b[0])
			if int(n) != wantRet || (wantRet == 1 && gotVal != wantVal) {
				if hostDiffs[key] {
					continue
				}
				mismatches++
				t.Errorf("Sscanf(%q,%q) = ret %d val %q; host ret %d val %q",
					input, fmtStr, n, gotVal, wantRet, wantVal)
			}
		}
	}
	if mismatches == 0 {
		t.Logf("all reference cases match host sscanf")
	}
}
